ART=Path('artifacts')
qa,eval_tab=st.tabs(['🔎 Ask a paper','📊 Parameter sweep dashboard'])

@st.cache_data(show_spinner='Loading papers...')
def papers_cached(n):return load_papers('dev',n)

@st.cache_resource(show_spinner='Loading embeddings...')
def embed_cached(model):return get_embedder(model)

@st.cache_resource(show_spinner='Indexing selected paper...')
def search_cached(pid,cfg_json):
    cfg=Config(**json.loads(cfg_json))
    papers=papers_cached(12)
    return SearchLab(pid,papers[pid],cfg,embed_cached(cfg.embed_model))

run_folder=ART/'runs'
@st.cache_data(ttl=10)
def fetch_runs():
    rows=[]
    for f in sorted(run_folder.glob('*_summary.json')) if run_folder.exists() else []:
        try:rows.append({'run':f.name.removesuffix('_summary.json'),**json.loads(f.read_text())})
        except (OSError,ValueError):pass
    return pd.DataFrame(rows)

def pareto_frontier(frame, quality, cost):
    """Configurations not dominated on higher quality and lower latency."""
    rows = frame[[quality, cost]].apply(pd.to_numeric, errors='coerce')
    valid = rows.notna().all(axis=1) & (rows[cost] >= 0)
    frontier = pd.Series(False, index=frame.index)
    for idx in rows.index[valid]:
        q, t = rows.loc[idx, quality], rows.loc[idx, cost]
        others = rows.loc[valid & (rows.index != idx)]
        dominated = ((others[quality] >= q) & (others[cost] <= t) &
                     ((others[quality] > q) | (others[cost] < t))).any()
        frontier.loc[idx] = not dominated
    return frontier


def run_questions(run):
    p = run_folder / f'{run}.json'
    if not p.exists():
        return pd.DataFrame()
    try:
        return pd.read_json(p)
    except (OSError, ValueError):
        return pd.DataFrame()


with eval_tab:
    st.subheader('Experiment leaderboard & diagnostics')
    df = fetch_runs()
    if df.empty:
        st.info('No experiments yet. Run the sweep cells in the notebook, then refresh.')
    else:
        selected = df.copy()
        filter_cols = st.columns(4)
        for col, key in zip(filter_cols, ['chunking','retrieval','transformation','rerank']):
            if key in df:
                options = sorted(df[key].dropna().unique().tolist(), key=str)
                chosen = col.multiselect(key, options, default=options, format_func=str)
                selected = selected[selected[key].isin(chosen)]

        nums = [k for k in [
            'chunk_size','overlap','semantic_buffer','semantic_percentile','window_size',
            'parent_chunk_size','child_chunk_size','merge_threshold','dense_top_k','sparse_top_k',
            'rrf_k','candidate_k','rerank_top_n','query_count'
        ] if k in selected.columns]
        with st.expander('Filter individual hyperparameters'):
            choice = st.selectbox('Parameter', nums) if nums else None
            if choice:
                values = sorted(selected[choice].dropna().unique().tolist())
                picked = st.multiselect('Include values', values, default=values)
                selected = selected[selected[choice].isin(picked)]

        metrics = [m for m in ['recall_at_k','precision_at_k','mrr_at_k','map_at_k',
                                'ndcg_at_k','hit_at_k','latency_s'] if m in selected.columns]
        if selected.empty or not metrics:
            st.warning('No matching experiments or numeric metrics.')
        else:
            for m in metrics:
                selected[m] = pd.to_numeric(selected[m], errors='coerce')
            a, b, c = st.columns([2,1,1])
            metric = a.selectbox('Primary accuracy metric', [m for m in metrics if m != 'latency_s'] or metrics,
                                 index=0)
            sort_ascending = b.checkbox('Lowest first', value=False)
            max_display = c.number_input('Display top N', min_value=5, max_value=500, value=30, step=5)
            selected = selected.sort_values(metric, ascending=sort_ascending, na_position='last').copy()
            st.caption(f'{len(selected)} matching experiments. All figures use saved experiment results; no simulated scores.')

            # Warning: mean metrics are directly comparable only with the same evaluated questions.
            for field in ['top_k','evaluated_questions','questions_mappable']:
                if field in selected and selected[field].nunique(dropna=True) > 1:
                    st.warning(f'Runs differ in {field}. Interpret accuracy comparisons with care.')

            tab_overview, tab_trades, tab_sensitivity, tab_failures = st.tabs([
                '🏆 Performance', '⚖️ Accuracy vs speed', '🎛️ Parameter sensitivity', '🔍 Outliers & failures'
            ])

            with tab_overview:
                st.markdown('#### Standout configurations')
                ranked = selected.dropna(subset=[metric]).copy()
                if len(ranked):
                    best = ranked.nlargest(1, metric).iloc[0]
                    low_lat = (selected.dropna(subset=['latency_s']).nsmallest(1,'latency_s').iloc[0]
                               if 'latency_s' in selected and selected['latency_s'].notna().any() else None)
                    base = selected[(selected.get('chunking')=='paragraph') &
                                    (selected.get('retrieval')=='dense') &
                                    (selected.get('transformation')=='none') &
                                    (selected.get('rerank')==False)]
                    cards = st.columns(3)
                    cards[0].metric('Best '+metric, f'{best[metric]:.3f}', help=str(best['run']))
                    if low_lat is not None:
                        cards[1].metric('Fastest query latency', f'{low_lat["latency_s"]:.3f} s',
                                        help=str(low_lat['run']))
                    if not base.empty and pd.notna(base.iloc[0][metric]):
                        cards[2].metric('Best vs paragraph baseline', f'{best[metric]-base.iloc[0][metric]:+.3f}',
                                        help='Absolute difference, not a causal estimate')
                    else:
                        cards[2].metric('Evaluated configurations', len(selected))

                    st.markdown('#### Top configurations')
                    top = ranked.head(max_display).copy()
                    top['label'] = top['run'].astype(str)
                    chart = alt.Chart(top).mark_bar().encode(
                        y=alt.Y('label:N', sort='-x', title='Experiment'),
                        x=alt.X(f'{metric}:Q', title=metric, scale=alt.Scale(zero=True)),
                        color=alt.Color('retrieval:N', legend=alt.Legend(title='Retriever')),
                        tooltip=['run:N','chunking:N','retrieval:N',alt.Tooltip(f'{metric}:Q',format='.3f'),
                                 alt.Tooltip('latency_s:Q',format='.3f')]
                    ).properties(height=max(280, min(800, len(top)*22)))
                    st.altair_chart(chart, use_container_width=True)

                st.markdown('#### All saved results')
                display = ['run','chunking','retrieval','transformation','rerank','top_k',
                           'chunk_size','overlap','semantic_buffer','semantic_percentile','window_size',
                           'merge_threshold','dense_top_k','sparse_top_k','rrf_k','rerank_top_n',
                           'evaluated_questions',*metrics]
                st.dataframe(selected[[x for x in display if x in selected]],hide_index=True,use_container_width=True)
                st.download_button('Export filtered runs as CSV', selected.to_csv(index=False).encode(),
                                   'ragxiv_filtered_results.csv','text/csv')

            with tab_trades:
                st.markdown('#### Accuracy–latency Pareto frontier')
                st.caption('A point is Pareto-optimal if no other configuration has both at least as good '
                           'accuracy and at most as high latency, with one strict improvement.')
                if 'latency_s' in selected and selected['latency_s'].notna().sum() >= 2:
                    trade = selected.dropna(subset=[metric,'latency_s']).copy()
                    trade['frontier'] = pareto_frontier(trade, metric, 'latency_s').map({True:'Pareto',False:'Dominated'})
                    trade['label'] = trade['run'].astype(str)
                    scat = alt.Chart(trade).mark_circle(size=110,opacity=.85).encode(
                        x=alt.X('latency_s:Q',title='Average query latency (seconds)'),
                        y=alt.Y(f'{metric}:Q',title=metric,scale=alt.Scale(zero=False)),
                        color=alt.Color('frontier:N',scale=alt.Scale(domain=['Pareto','Dominated'],range=['#0d9488','#94a3b8'])),
                        shape='retrieval:N',
                        tooltip=['run:N','chunking:N','retrieval:N',alt.Tooltip(f'{metric}:Q',format='.3f'),
                                 alt.Tooltip('latency_s:Q',format='.3f')]
                    ).interactive().properties(height=390)
                    st.altair_chart(scat,use_container_width=True)
                    st.markdown('#### Non-dominated configurations')
                    st.dataframe(trade[trade['frontier']=='Pareto'][['run',metric,'latency_s','chunking','retrieval']]
                                 .sort_values(metric,ascending=False),hide_index=True,use_container_width=True)
                else:
                    st.info('At least two runs with latency measurements are required.')

                if 'retrieval' in selected and selected['retrieval'].nunique()>1:
                    st.markdown('#### Retrieval method comparison')
                    grouped=selected.groupby('retrieval',as_index=False).agg(
                        avg_metric=(metric,'mean'),n_runs=('run','count'))
                    st.altair_chart(alt.Chart(grouped).mark_bar().encode(
                        x='retrieval:N',y=alt.Y('avg_metric:Q',title='Average '+metric),
                        tooltip=['retrieval:N','n_runs:Q','avg_metric:Q']
                    ),use_container_width=True)
                    st.caption('Descriptive averages only: different retrieval groups may have different chunking settings.')

            with tab_sensitivity:
                st.markdown('#### Hyperparameter sensitivity')
                varying = [x for x in nums if selected[x].nunique(dropna=True)>1]
                if varying:
                    param = st.selectbox('Parameter to plot', varying)
                    pdat=selected[[param,metric,'run','chunking','retrieval']].dropna(subset=[param,metric]).copy()
                    pdat[param]=pdat[param].astype(str)
                    points=alt.Chart(pdat).mark_circle(size=85,opacity=.65).encode(
                        x=alt.X(f'{param}:N',title=param),y=alt.Y(f'{metric}:Q',scale=alt.Scale(zero=False)),
                        color='chunking:N',tooltip=['run:N',f'{param}:N',f'{metric}:Q','retrieval:N']
                    )
                    means=alt.Chart(pdat).mark_tick(color='black',size=32,thickness=3).encode(
                        x=alt.X(f'{param}:N'), y=f'mean({metric}):Q'
                    )
                    st.altair_chart((points+means).properties(height=320),use_container_width=True)
                    st.caption('Dots are individual runs; dark ticks are group means. This is NOT a controlled '
                               'effect estimate if other settings vary between runs.')
                else:
                    st.info('Run at least two values of a parameter to see a sensitivity plot.')

                if {'chunking','retrieval',metric}.issubset(selected.columns):
                    st.markdown('#### Chunking × retrieval heatmap')
                    heat=selected.groupby(['chunking','retrieval'],as_index=False).agg(
                        mean_score=(metric,'mean'),n_runs=('run','count'))
                    heatmap=alt.Chart(heat).mark_rect().encode(
                        x='retrieval:N',y='chunking:N',
                        color=alt.Color('mean_score:Q',title='Mean '+metric,scale=alt.Scale(scheme='tealblues')),
                        tooltip=['chunking:N','retrieval:N','n_runs:Q',alt.Tooltip('mean_score:Q',format='.3f')]
                    ).properties(height=280)
                    st.altair_chart(heatmap,use_container_width=True)
                    st.caption('Empty combinations were not tested. Cells average matching configurations only.')

            with tab_failures:
                st.markdown('#### Per-question distributions and hard cases')
                runs = selected['run'].tolist()
                chosen_run = st.selectbox('Inspect experiment',runs,key='inspect_run')
                questions = run_questions(chosen_run)
                if questions.empty:
                    st.warning('Per-question results unavailable for this run.')
                else:
                    qmetrics=[m for m in metrics if m in questions]
                    if qmetrics:
                        qm=st.selectbox('Question-level metric',qmetrics,index=qmetrics.index(metric) if metric in qmetrics else 0)
                        qdist=questions[[qm]].copy()
                        qdist[qm]=pd.to_numeric(qdist[qm],errors='coerce')
                        histogram=alt.Chart(qdist.dropna()).mark_bar().encode(
                            x=alt.X(f'{qm}:Q',bin=alt.Bin(maxbins=16),title=qm),
                            y=alt.Y('count():Q',title='Number of questions')
                        ).properties(height=220)
                        st.altair_chart(histogram,use_container_width=True)
                        if qm!='latency_s':
                            hard=questions.sort_values(qm,ascending=True).head(10)
                            st.markdown('**Lowest-scoring questions**')
                        else:
                            hard=questions.sort_values(qm,ascending=False).head(10)
                            st.markdown('**Slowest questions**')
                        cols=[k for k in ['paper_title','question',qm,'gold_count'] if k in hard]
                        st.dataframe(hard[cols],hide_index=True,use_container_width=True)
                    idx=st.number_input('Inspect question index',min_value=0,max_value=len(questions)-1,value=0)
                    q=questions.iloc[int(idx)]
                    st.write('**Question:**',q.get('question',''))
                    st.write('Gold source paragraph IDs:',q.get('gold_ids',[]))
                    st.write('Retrieved source paragraph IDs:',q.get('retrieved_ids',[]))
                    for j,ctx in enumerate(q.get('contexts',[]),1):
                        with st.expander(f'Retrieved passage {j}'):
                            st.write(ctx)

                st.markdown('#### Frequently missed questions across configurations')
                st.caption('Only questions evaluated by at least two selected runs appear. '
                           'Run coverage can differ because of missing evidence mappings.')
                counters=[]
                for name in runs[:100]:
                    qdf=run_questions(name)
                    if qdf.empty or not {'question_id','recall_at_k'}.issubset(qdf):continue
                    for _,r in qdf.iterrows():
                        counters.append({'question_id':str(r['question_id']),'question':r.get('question',''),
                                         'run':name,'recall':r['recall_at_k']})
                if counters:
                    cdf=pd.DataFrame(counters).groupby(['question_id','question'],as_index=False).agg(
                        n_runs=('run','nunique'),mean_recall=('recall','mean'),
                        missed_rate=('recall',lambda x:float((pd.to_numeric(x,errors='coerce')==0).mean())))
                    cdf=cdf[cdf['n_runs']>=2].sort_values(['missed_rate','n_runs'],ascending=[False,False])
                    st.dataframe(cdf.head(15),hide_index=True,use_container_width=True)

    for filename,title in [('generation_scores.csv','Local LLM groundedness / context relevance / answer relevance'),
                           ('ragas_scores.csv','Official RAGAS metrics')]:
        p=ART/filename
        if p.exists():
            st.subheader(title)
            try:
                llm_df=pd.read_csv(p)
                st.dataframe(llm_df,use_container_width=True,hide_index=True)
                candidate=[x for x in ['groundedness','context_relevance','answer_relevance',
                                        'faithfulness','answer_relevancy','context_precision','context_recall']
                           if x in llm_df and pd.to_numeric(llm_df[x],errors='coerce').notna().any()]
                if candidate:
                    long=llm_df[candidate].apply(pd.to_numeric,errors='coerce').melt(
                        var_name='metric',value_name='score').dropna()
                    chart=alt.Chart(long).mark_boxplot().encode(x='metric:N',y='score:Q',color='metric:N')
                    st.altair_chart(chart.properties(height=250),use_container_width=True)
                    st.caption('LLM-judge scores are shown separately from deterministic retrieval metrics.')
            except (OSError,ValueError) as exc:
                st.warning(f'Unable to read {filename}: {exc}')

with qa:
    st.info('Ask questions about one paper. Retrieval is local; Ollama is required for generated answers and query transformations.')
    try: papers=papers_cached(12)
    except Exception as exc:
        st.error(f'Cannot load QASPER: {exc}')
        st.stop()
    choices={f'{p.get("title",pid)} — {pid}':pid for pid,p in papers.items()}
    selected_title=st.selectbox('Paper',list(choices))
    runs=fetch_runs()
    if not runs.empty:
        chosen_run=st.selectbox('Use an evaluated experiment configuration', ['Manual']+runs['run'].tolist())
    else:chosen_run='Manual'
    if chosen_run!='Manual':
        record=runs[runs['run']==chosen_run].iloc[0].to_dict()
        cfg=Config(**{name:record[name] for name in Config.__dataclass_fields__ if name in record and pd.notna(record[name])})
        st.json({name:getattr(cfg,name) for name in ('chunking','retrieval','rerank','transformation','chunk_size','overlap','top_k','rrf_k')})
    else:
        a,b,c,d=st.columns(4)
        chunk=a.selectbox('Chunking',['paragraph','fixed','recursive','semantic','sentence_window','parent','auto_merging'])
        retrieval=b.selectbox('Retrieval',['dense','bm25','hybrid'])
        transform=c.selectbox('Query transform',['none','rewrite','multi_query','hyde'])
        rerank=d.checkbox('Cross-encoder reranking')
        a,b,c,d=st.columns(4)
        sz=a.number_input('Chunk size',64,2048,256,64)
        ov=b.number_input('Overlap',0,512,32,8)
        k=c.number_input('Top K',1,20,5)
        rrf=d.number_input('RRF k',1,200,60)
        cfg=Config(chunking=chunk,retrieval=retrieval,transformation=transform,rerank=rerank,
                   chunk_size=sz,overlap=ov,top_k=k,rrf_k=rrf)
    prompt=st.text_input('Your question','What are the main limitations of the proposed approach?')
    answer_on=st.checkbox('Generate response with local Ollama',value=False)
    if st.button('Retrieve / Answer',type='primary') and prompt.strip():
        if cfg.chunking in ('fixed','recursive') and cfg.overlap>=cfg.chunk_size:
            st.error('Overlap must be smaller than chunk size.')
        else:
            try:
                lab=search_cached(choices[selected_title],json.dumps(vars(cfg),sort_keys=True))
                started=time.perf_counter()
                hits=lab.search(prompt)
                st.caption(f'{len(hits)} retrieved passages in {time.perf_counter()-started:.2f}s')
                if answer_on:
                    st.subheader('Answer with citations')
                    st.write(generate_answer(prompt,hits,cfg))
                st.subheader('Retrieved evidence')
                for j,h in enumerate(hits,1):
                    with st.expander(f'[{j}] {h.node.metadata.get("section","Section")} · {h.node.metadata.get("source_pid", "unknown")}',expanded=j<=2):
                        st.write(passage(h,cfg))
            except Exception as exc:st.exception(exc)
